    <tool-call call-id="c34" name="write_file"><arguments>{"content":"# Supabase stack configuration (copy to supabase/.env, never commit the copy).\n#\n# Generate secrets with:\n#   openssl rand -hex 32            # POSTGRES_PASSWORD\n#   openssl rand -base64 48 | tr -d '\\n'   # JWT_SECRET (at least 32 characters)\n#\n# The anon key is a public client key. RLS is what protects user data.\n# The service_role key (if you generate one) is server-only and must never\n# be placed in browser-served files.\n\n# --- Images (pin exact digests after your first successful deploy) ---\nPOSTGRES_IMAGE=supabase/postgres:15.8.1.085\nGOTRUE_IMAGE=supabase/gotrue:v2.197.0\nPOSTGREST_IMAGE=postgrest/postgrest:v12.2.3\nGATEWAY_IMAGE=caddy:2-alpine\n\n# --- Postgres ---\nPOSTGRES_DB=postgres\nPOSTGRES_PASSWORD=change-me-postgres-password-min-32-chars-long-please\nPOSTGRES_PORT=5432\n\n# --- Network ---\n# Bind to localhost and put a real reverse proxy with TLS in front for production.\nBIND_ADDR=127.0.0.1\nSUPABASE_PORT=8000\n\n# --- Public URLs ---\n# What browsers use for Auth + PostgREST (served by the gateway service).\nSUPABASE_PUBLIC_URL=http://localhost:8000\n# Full external Auth URL used for OAuth callbacks and email links.\nAPI_EXTERNAL_URL=http://localhost:8000/auth/v1\n# Public URL of this Node app (used for Auth redirect allow-listing and email links).\nSITE_URL=http://localhost:3000\n# Optional extra comma-separated redirect URLs (staging domains, LAN addresses).\nAPP_EXTRA_REDIRECT_URLS=\n\n# --- Auth ---\nJWT_SECRET=change-me-jwt-secret-at-least-32-characters-long-please\nGOTRUE_JWT_EXP=3600\n# Set false until real SMTP is configured; true skips email confirmation.\nGOTRUE_MAILER_AUTOCONFIRM=false\n\n# --- SMTP (required for confirmation + password-reset emails) ---\nSMTP_HOST=\nSMTP_PORT=587\nSMTP_USER=\nSMTP_PASS=\nSMTP_ADMIN_EMAIL=\nSMTP_SENDER_NAME=AI Chat WebUI\nSMTP_MAX_FREQUENCY=1s\n\n# --- Component ports (localhost only) ---\nGOTRUE_PORT=9999\nPOSTGREST_PORT=3001\n","path":"supabase/.env.example"}</arguments></tool-call>
